// Semilla basada en timestamp actual
const seed = Math.floor(Date.now() / (1000 * 60 * 5));
const item = CIUDADES[seed % CIUDADES.length];

// Query ultrarrápida para nodes de comercios/empresas con email
const query = `[out:json][timeout:15];
(
  node["email"]${item.bbox};
  node["contact:email"]${item.bbox};
);
out tags;`;

return [{
  json: {
    query: query,
    ciudad: item.ciudad
  }
}];

const raw = $input.first()?.json || {};
const elements = raw.elements || [];
const meta = $('Generar Region y Query Overpass').first()?.json || {};

const leads = [];
const seenEmails = new Set();

const BLACKLIST = [
  'sentry.io', 'wixpress.com', 'example.com', 'schema.org', 'googleapis.com', 
  'cloudflare.com', 'facebook.com', 'instagram.com', 'google.com', 'test@', 'support@', 'noreply@'
];

for (const el of elements) {
  const tags = el.tags || {};
  const name = tags.name || tags.operator || tags.brand || '';
  if (!name || name.length < 2) continue;

  const rawEmail = tags.email || tags['contact:email'] || '';
  if (!rawEmail || !rawEmail.includes('@')) continue;

  const splitEmails = rawEmail.split(/[,;\s]+/).filter(e => e.includes('@'));

  const phone = tags.phone || tags['contact:phone'] || tags['contact:mobile'] || tags['contact:whatsapp'] || '';
  const website = tags.website || tags['contact:website'] || tags['contact:facebook'] || tags['contact:instagram'] || '';
  const rubro = tags.shop || tags.amenity || tags.office || tags.craft || tags.commercial || tags.tourism || 'Empresa / Comercio';

  for (const e of splitEmails) {
    const email = e.toLowerCase().trim().replace(/[.,;:]+$/, '');
    if (email.length < 6 || email.length > 65) continue;
    if (BLACKLIST.some(b => email.includes(b))) continue;
    if (seenEmails.has(email)) continue;

    seenEmails.add(email);

    let cleanPhone = phone.replace(/\D/g, '');
    let displayPhone = '-';
    let linkWa = '-';
    if (cleanPhone.length >= 8) {
      if (!cleanPhone.startsWith('54')) cleanPhone = '549' + cleanPhone;
      displayPhone = '+' + cleanPhone;
      linkWa = 'https://wa.me/' + cleanPhone;
    }

    leads.push({
      'Nombre del Negocio': name,
      'Email': email,
      'Teléfono WhatsApp': displayPhone,
      'Link WhatsApp': linkWa,
      'Categoría / Rubro': rubro.replace(/_/g, ' '),
      'Ciudad': meta.ciudad || 'Argentina',
      'País': 'AR',
      'Instagram URL': website.includes('instagram.com') ? website : '-',
      'Tiene Sitio Web': (website && !website.includes('instagram.com') && !website.includes('facebook.com')) ? 'Sí' : 'No',
      'Enlace / Web': website || '-',
      'Dolor Detectado': 'Oportunidad de automatización y venta de sistemas.',
      'Solución Propuesta': '🚀 Sistema Web / Gestión + Campaña B2B.',
      'Estado': '🟢 Email Verificado',
      'Fecha Extracción': new Date().toISOString().replace('T', ' ').slice(0, 16)
    });
  }
}

return leads.map(l => ({ json: l }));
